-- Synthetic disposable database only. No deployment envelope, network calls or production data.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL search_path=pg_catalog,public;
SET LOCAL TimeZone='UTC';
SET LOCAL statement_timeout='120s';
DO $empty$ BEGIN
 IF current_setting('server_version_num')::int NOT BETWEEN 170000 AND 179999 THEN RAISE EXCEPTION 'PG17 required'; END IF;
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN('r','v','m','p','f')) OR to_regnamespace('auth') IS NOT NULL THEN RAISE EXCEPTION 'empty disposable database required'; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN('fixture_owner','service_role','anon','authenticated')) THEN RAISE EXCEPTION 'fresh disposable roles required'; END IF;
END $empty$;
CREATE ROLE fixture_owner NOLOGIN NOSUPERUSER BYPASSRLS;
CREATE ROLE service_role NOLOGIN NOSUPERUSER BYPASSRLS;
CREATE ROLE anon NOLOGIN NOSUPERUSER NOBYPASSRLS;
CREATE ROLE authenticated NOLOGIN NOSUPERUSER NOBYPASSRLS;
GRANT USAGE,CREATE ON SCHEMA public TO fixture_owner;
CREATE SCHEMA auth AUTHORIZATION fixture_owner;
SET LOCAL ROLE fixture_owner;
CREATE TABLE public.fixture_test_log(label text PRIMARY KEY);
CREATE FUNCTION public.fixture_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $assert$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'fixture failed: %',label; END IF; INSERT INTO public.fixture_test_log VALUES(label); END $assert$;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $uid$ SELECT nullif(current_setting('fixture.uid',true),'')::uuid $uid$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS $jwt$ SELECT jsonb_build_object('email',coalesce(current_setting('fixture.email',true),'')) $jwt$;
