CREATE FUNCTION public.fixture_pin(e public.lts_reconciliation_evidence) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $pin$ SELECT encode(sha256(convert_to(jsonb_build_object('schema','q26-evidence-immutable-v2','evidence',jsonb_build_object('id',e.id,'user_id',e.user_id,'evidence_date',e.evidence_date,'account',e.account,'amount',e.amount,'description',e.description,'evidence_type',e.evidence_type,'source_ref',e.source_ref,'status',e.status),'contract',e.metadata->'contract')::text,'UTF8')),'hex') $pin$;
UPDATE public.lts_reconciliation_evidence e SET metadata=jsonb_set(metadata,'{immutable_fingerprint}',to_jsonb(public.fixture_pin(e)));
INSERT INTO public.fixture_control SELECT 'pin',to_jsonb(public.fixture_pin(e)) FROM public.lts_reconciliation_evidence e WHERE id='55555555-5555-4555-8555-555555555555';
