CREATE FUNCTION public.fixture_reset() RETURNS void LANGUAGE plpgsql AS $reset$ DECLARE r record; BEGIN
 FOR r IN SELECT * FROM public.fixture_snapshots LOOP EXECUTE format('TRUNCATE public.%I',r.name); EXECUTE format('INSERT INTO public.%I SELECT * FROM jsonb_populate_recordset(NULL::public.%I,$1)',r.name,r.name) USING r.payload; END LOOP;
 PERFORM set_config('fixture.uid',$fixture_data$11111111-1111-4111-8111-111111111111$fixture_data$,true); PERFORM set_config('fixture.email','owner@example.invalid',true);
END $reset$;
CREATE FUNCTION public.fixture_install(kind text) RETURNS void LANGUAGE plpgsql AS $install$ DECLARE r record; p text; BEGIN
 SELECT value#>>'{}' INTO STRICT p FROM public.fixture_control WHERE key='pin';
 FOR r IN SELECT ddl FROM public.fixture_templates WHERE name LIKE '%_'||kind ORDER BY name LOOP
  EXECUTE replace(r.ddl,'UNBOUND_CANONICAL_SHA256_REQUIRES_PG17_REVIEW',p);
 END LOOP;
END $install$;
SELECT public.fixture_install('original');
CREATE FUNCTION public.fixture_capture() RETURNS jsonb LANGUAGE sql AS $capture$
 SELECT jsonb_build_object('expense',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text),'[]') FROM public.lts_v229_expense_rows(auth.uid(),'2020-10-01','2020-10-16') r),
 'card',public.lts_browser_card_detail_v226('aeternum','2020-10-01'),
 'november',public.lts_browser_card_detail_v226('aeternum','2020-11-01'),
 'core',public.lts_card_cycles_v226(auth.uid()));
$capture$;
CREATE TABLE public.fixture_case_results(label text PRIMARY KEY,original jsonb,candidate jsonb,expense_active boolean,card_active boolean);
CREATE FUNCTION public.fixture_expected_card(v jsonb) RETURNS jsonb LANGUAGE plpgsql AS $expected$ DECLARE items jsonb; prior jsonb; amt numeric; n bigint; out jsonb; BEGIN
 SELECT x INTO STRICT prior FROM jsonb_array_elements(v->'items') x WHERE x->>'source_id'=$fixture_data$33333333-3333-4333-8333-333333333333$fixture_data$;
 SELECT jsonb_agg(x ORDER BY ord),sum((x->>'amount')::numeric),count(*) INTO items,amt,n FROM jsonb_array_elements(v->'items') WITH ORDINALITY a(x,ord) WHERE x->>'source_id'<>$fixture_data$33333333-3333-4333-8333-333333333333$fixture_data$;
 out:=v||jsonb_build_object('items',items,'amount',amt,'item_count',n,'difference',(v->>'invoice_amount')::numeric-amt,
 'unclassified',(SELECT count(*) FROM jsonb_array_elements(items) x WHERE x->>'category_basis'='unresolved'),
 'categories',(SELECT jsonb_agg(to_jsonb(z) ORDER BY category) FROM (SELECT x->>'category' category,count(*) n,sum((x->>'amount')::numeric) amount FROM jsonb_array_elements(items) x GROUP BY 1) z),
 'instruments',(SELECT jsonb_agg(to_jsonb(z) ORDER BY last4) FROM (SELECT x->>'last4' last4,count(*) n,sum((x->>'amount')::numeric) amount FROM jsonb_array_elements(items) x GROUP BY 1) z),
 'reconciliation_provenance',jsonb_build_object('operation_id',$fixture_data$55555555-5555-4555-8555-555555555555$fixture_data$,'evidence_id',$fixture_data$55555555-5555-4555-8555-555555555555$fixture_data$,'basis','owner_confirmed_nominal_composite_identity','representative_source_id',$fixture_data$22222222-2222-4222-8222-222222222222$fixture_data$,'not_additional_expenses',true,'prior_observation',prior));
 IF v ? 'detail_total' THEN out:=jsonb_set(out,'{detail_total}',to_jsonb(amt)); END IF;
 RETURN out;
END $expected$;
CREATE FUNCTION public.fixture_case(label text,mutation text,expense_active boolean,card_active boolean) RETURNS void LANGUAGE plpgsql AS $case$ DECLARE a jsonb;b jsonb;expected jsonb;ex jsonb; BEGIN
 PERFORM public.fixture_reset(); IF mutation<>'' THEN EXECUTE mutation; END IF;
 PERFORM public.fixture_install('original'); a:=public.fixture_capture();
 PERFORM public.fixture_install('candidate'); b:=public.fixture_capture(); expected:=a;
 IF expense_active THEN SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') INTO ex FROM jsonb_array_elements(a->'expense') x WHERE NOT(x->>'source_ref'=$fixture_data$33333333-3333-4333-8333-333333333333$fixture_data$ AND x->>'competence_month'='2020-10-01'); expected:=jsonb_set(expected,'{expense}',ex); END IF;
 IF card_active THEN expected:=jsonb_set(expected,'{card}',public.fixture_expected_card(a->'card')); END IF;
 PERFORM public.fixture_assert(b=expected,label);
 INSERT INTO public.fixture_case_results VALUES(label,a,b,expense_active,card_active);
END $case$;
SELECT public.fixture_install('original');
