CREATE TABLE public.fixture_compiled(variant text,signature text,definition text,prosrc text,definition_md5 text,result text,language text,security_definer boolean,volatility text,config text[],owner text,acl text[]);
CREATE FUNCTION public.fixture_record_compiled(v text) RETURNS void LANGUAGE sql AS $compiled$
 INSERT INTO public.fixture_compiled SELECT v,p.oid::regprocedure::text,pg_get_functiondef(p.oid),p.prosrc,md5(pg_get_functiondef(p.oid)),pg_get_function_result(p.oid),l.lanname,p.prosecdef,p.provolatile,p.proconfig,pg_get_userbyid(p.proowner),p.proacl::text[] FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid IN('public.lts_v229_expense_rows(uuid,date,date)'::regprocedure,'public.lts_browser_card_detail_v226(text,date)'::regprocedure);
$compiled$;
SELECT public.fixture_record_compiled('original');
