CREATE FUNCTION public.fixture_guard_error(kind text,uid text,email text,family text DEFAULT 'aeternum') RETURNS text LANGUAGE plpgsql AS $err$ DECLARE code text;msg text; BEGIN
 PERFORM public.fixture_install(kind); PERFORM set_config('fixture.uid',uid,true);PERFORM set_config('fixture.email',email,true);
 BEGIN PERFORM public.lts_browser_card_detail_v226(family,'2020-10-01'); RETURN 'NO_ERROR'; EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS code=RETURNED_SQLSTATE,msg=MESSAGE_TEXT; RETURN code||':'||msg; END;
END $err$;
